            act[pc.outOff + r * pc.gemmN + nt * TILE + col] = v;
#else
            // The partials ride `resOff`, which no MODE 2 caller uses: the
            // push block is 64 uints, this device's whole range, and the wide
            // residual is the hyper-connection block's tensor alone
            // (llm_common.glsl). Row-major over the slab, so MODE 1's sum is
            // contiguous.
            act[pc.resOff + (r * KSLABS + slab) * pc.gemmN + nt * TILE + col] = v;
#endif
        }
    }
#else
    uint n = gl_GlobalInvocationID.x;
    uint r = gl_WorkGroupID.y;                   // which row of A, P5b
    if (n >= pc.gemmN || r >= ROWS) {
        return;
    }
    float sum = 0.0;
    [[unroll]] for (uint s = 0u; s < KSLABS; s++) {
        sum += act[pc.resOff + (r * KSLABS + s) * pc.gemmN + n];
    }
    act[pc.outOff + r * pc.gemmN + n] = sum;
#endif
}
