}

func hexUpper(v uint32, n int) string {
	const digits = "0123456789ABCDEF"
	out := make([]byte, n)
	for i := n - 1; i >= 0; i-- {
		out[i] = digits[v&15]
		v >>= 4
	}
	return string(out)
}

