func TestDebugPeaks(t *testing.T) {
	m := loadLMManifest(t)
	g := loadGPU(t)
	rows := promptRows(t, m, "given_duration", 1)
	n := len(rows[0]) - 1
	var pre []Tok
	for i := 0; i < n; i++ {
		pre = append(pre, Tok{ID: rows[0][i], Slot: 0, Pos: i})
	}
	// upload as Pass does, by running a zero-layer pass
	saved := g.w
	g.w = nil
	g.Pass(pre, Range{})
	g.w = saved
	chunks, chunkLen := 4, 64
	for i := range g.w {
		d := g.layerGraph(i, n, chunks, chunkLen)
		if _, err := vk.DispatchMultiTimed(d, 1, 1, true); err != nil {
			t.Fatal(err)
		}
		gt := g.abuf.ReadFloat32At(int(g.aGate), n*ffn)
		up := g.abuf.ReadFloat32At(int(g.aUp), n*ffn)
		x := g.abuf.ReadFloat32At(int(g.aX), n*hidden)
		ff := g.abuf.ReadFloat32At(int(g.aFF), n*hidden)
		var pk, xk, fk float64
		pr := 0
		for j := range gt {
			gv := float64(gt[j])
			p := math.Abs(gv / (1 + math.Exp(-gv)) * float64(up[j]))
			if p > pk || math.IsNaN(p) {
				pk, pr = p, j/ffn
			}
		}
		for j := range x {
			xk = math.Max(xk, math.Abs(float64(x[j])))
			fk = math.Max(fk, math.Abs(float64(ff[j])))
		}
		t.Logf("layer %2d: swiglu peak %.4g (row %d, tok %d), down out %.4g, residual %.4g", i, pk, pr, rows[0][pr], fk, xk)
	}
}
EOF
