// taking the sampled token as the argmax at each step.
func TestFSMTrace(t *testing.T) {
	m := loadLMManifest(t)
	tk := loadTokenizer(t)
	v, err := newFSMVocab(tk)
	if err != nil {
		t.Fatal(err)
	}
	c := m.Cases["given_duration"]
