func NewPlanner(g *GPU, tk *tokenizer.Tokenizer) (*Planner, error) {
	v, err := newFSMVocab(tk)
	if err != nil {
		return nil, err
	}
	return &Planner{G: g, Tk: tk, S: DefaultSampling, v: v}, nil
}

