package api

// OpenAI's asynchronous video API (VIDEO.md M9), which is also what SGLang
// serves MiniMax-H3 behind:
//
//	POST   /v1/videos               -> a job, queued
//	GET    /v1/videos               -> the jobs, newest first
//	GET    /v1/videos/{id}          -> one job's status and progress
//	GET    /v1/videos/{id}/content  -> the mp4, once completed
//	DELETE /v1/videos/{id}          -> cancel it if running, and forget it
//
// **The queue is here and not in the backend.** A video is ~14 minutes at
// the served 480p and ~2 hours at the trained 768p, so no client holds a
// connection open for one; the job, its progress and its file are transport
// state, the same for any model behind the door. The backend is synchronous
// (VideoBackend.GenerateVideo, one mp4 to a path it is handed), and this file
// runs one job at a time through it: the model's stagings hold 50 GB at their
// peak, and two at once would not fit, never mind go faster.
//
// Jobs live in memory. A restart forgets them, and their files with them:
// what a client holds is an id that 404s, which is what an expired job looks
// like too.

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"image"
	"io"
	"mime"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"strix-halo-vulkan/util"
)

// VideoBackend generates one video at a time, synchronously.
type VideoBackend interface {
	Backend
	// PlanVideo validates a request and resolves it -- canvas, frames,
	// steps, seed -- without touching the device. It is called when the job
	// is submitted, so a request that cannot run is a 400 then, and not a
	// failed job twenty minutes later. An error wrapping ErrUnsupported is
	// the client's.
	PlanVideo(req *VideoRequest) (*VideoPlan, error)
	// GenerateVideo runs a planned request and writes an mp4 to dst.
	// progress is called as it moves; ctx cancels it (DELETE, shutdown).
	GenerateVideo(ctx context.Context, req *VideoRequest, plan *VideoPlan, dst string, progress func(VideoProgress)) error
	// VideoGeometry is what the backend accepts, for GET /v1/models.
	VideoGeometry() VideoGeometry
}

// VideoRequest is a video request after the HTTP layer has parsed it, from
// either envelope: OpenAI's (`size`, `seconds`) or SGLang's H3 one
// (`target.short_edge`, `target.aspect_ratio`, `target.duration_seconds`).
type VideoRequest struct {
	Model  string
	Prompt string
	// AspectW:AspectH and ShortEdge are the canvas as H3 asks for one. An
	// OpenAI `size` becomes both: its ratio, and its shorter side. Zero takes
	// the backend's default.
	AspectW, AspectH float64
	ShortEdge        int
	// Seconds is the duration; zero takes the backend's default.
	Seconds float64
	// Steps is the sampling schedule's length; zero takes the default.
	Steps int
	// Seed is the noise seed; nil draws one, and the plan reports it.
	Seed *int64
	// Keyframes are fl2va's pictures (VIDEO.md M10): at most one for the
	// first frame and one for the last. None is t2va.
	Keyframes []VideoKeyframe
}

// VideoKeyframe is one keyframe: a decoded picture and the frame it pins,
// SGLang's `frame_index` — 0 for the first frame, and -1 (or any index at
// or past the clip's last frame, which the backend resolves) for the last.
type VideoKeyframe struct {
	Image      image.Image
	FrameIndex int
}

// VideoPlan is what a request resolves to.
type VideoPlan struct {
	Width, Height int
	Frames        int
	Seconds       float64 // Frames at the frame rate: what the clip will actually run
	Steps         int
	Seed          int64
	PromptTokens  int
	// Estimate is the backend's guess at the run's wall time, from measured
	// rates. It is reported so a client can tell a four-minute job from a
	// two-hour one before it starts.
	Estimate time.Duration
}

// VideoProgress is a running job's position: a stage name and the fraction
// of the whole run done.
type VideoProgress struct {
	Stage    string
	Fraction float64
}

// VideoGeometry is reported on the model object in GET /v1/models.
type VideoGeometry struct {
	DefaultSize    string  `json:"default_size"`
	DefaultSeconds float64 `json:"default_seconds"`
	MinSeconds     float64 `json:"min_seconds"`
	MaxSeconds     float64 `json:"max_seconds"`
	MaxShortEdge   int     `json:"max_short_edge"`
	DefaultSteps   int     `json:"default_steps"`
	FPS            int     `json:"fps"`
	SampleRate     int     `json:"audio_sample_rate"`
}

// Video job statuses, as OpenAI names them.
const (
	VideoQueued     = "queued"
	VideoInProgress = "in_progress"
	VideoCompleted  = "completed"
	VideoFailed     = "failed"
)

// VideoJob is OpenAI's video object, plus the extensions a client of this
// model needs: the seed and step count it ran with, the frame count, the
// stage it is in, and an estimate of its wall time.
type VideoJob struct {
	ID          string      `json:"id"`
	Object      string      `json:"object"` // "video"
	Model       string      `json:"model"`
	Status      string      `json:"status"`
	Progress    int         `json:"progress"` // 0-100
	CreatedAt   int64       `json:"created_at"`
	CompletedAt *int64      `json:"completed_at"`
	ExpiresAt   *int64      `json:"expires_at"`
	Prompt      string      `json:"prompt"`
	Size        string      `json:"size"`
	Seconds     string      `json:"seconds"`
	Quality     string      `json:"quality"`
	Error       *VideoError `json:"error"`
	Remixed     *string     `json:"remixed_from_video_id"`

	Seed      int64   `json:"seed"`
	Steps     int     `json:"steps"`
	Frames    int     `json:"frames"`
	Stage     string  `json:"stage,omitempty"`
	Estimated float64 `json:"estimated_seconds"`
}

// VideoError is why a job failed.
type VideoError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// videoJob is a job and what only the queue sees.
type videoJob struct {
	VideoJob
	req    *VideoRequest
	plan   *VideoPlan
	path   string
	cancel context.CancelFunc // set while it runs
	gone   bool               // deleted; the worker skips it or discards its result
}

// VideoJobs is the queue and the store, and what Server.Videos is.
type VideoJobs struct {
	backend VideoBackend
	dir     string
	ownDir  bool
	ttl     time.Duration

	mu    sync.Mutex
	jobs  map[string]*videoJob
	queue chan *videoJob

	ctx    context.Context
	stop   context.CancelFunc
	done   chan struct{}
	closed sync.Once
}

// VideoJobsOptions configures NewVideoJobs.
type VideoJobsOptions struct {
	// Dir is where finished mp4s are kept until they expire. Empty makes a
	// temporary directory, removed on Close.
	Dir string
	// TTL is how long a finished job and its file are kept (0: 24 h).
	TTL time.Duration
	// MaxQueued bounds the jobs waiting behind the running one (0: 16). A
	// full queue is a 429: at 14 minutes a job, sixteen is most of a day.
	MaxQueued int
}

// NewVideoJobs starts the worker over b.
func NewVideoJobs(b VideoBackend, opt VideoJobsOptions) (*VideoJobs, error) {
	if opt.TTL <= 0 {
		opt.TTL = 24 * time.Hour
	}
	if opt.MaxQueued <= 0 {
		opt.MaxQueued = 16
	}
	q := &VideoJobs{backend: b, dir: opt.Dir, ttl: opt.TTL, jobs: map[string]*videoJob{},
		queue: make(chan *videoJob, opt.MaxQueued), done: make(chan struct{})}
	if q.dir == "" {
		d, err := os.MkdirTemp("", "videos-")
		if err != nil {
			return nil, err
		}
		q.dir, q.ownDir = d, true
	} else {
		if err := os.MkdirAll(q.dir, 0o755); err != nil {
			return nil, err
		}
		// A previous process's files: its jobs are gone, so nothing can
		// ever ask for them.
		old, _ := filepath.Glob(filepath.Join(q.dir, "video_*.mp4"))
		for _, f := range old {
			os.Remove(f)
		}
	}
	q.ctx, q.stop = context.WithCancel(context.Background())
	go q.work()
	return q, nil
}

// Close cancels the running job, fails the queued ones, and waits for the
// worker. It must run before the backend is closed.
func (q *VideoJobs) Close() {
	q.closed.Do(func() {
		q.stop()
		<-q.done
		if q.ownDir {
			os.RemoveAll(q.dir)
		}
	})
}

// Dir is where the finished files are.
func (q *VideoJobs) Dir() string { return q.dir }

func newVideoID() string {
	var b [16]byte
	_, _ = rand.Read(b[:])
	return "video_" + hex.EncodeToString(b[:])
}

// ErrQueueFull is a submit past MaxQueued.
var ErrQueueFull = errors.New("the video queue is full")

// Submit plans a request and queues it.
func (q *VideoJobs) Submit(req *VideoRequest) (VideoJob, error) {
	plan, err := q.backend.PlanVideo(req)
	if err != nil {
		return VideoJob{}, err
	}
	model := req.Model
	if ms := q.backend.Models(); len(ms) > 0 {
		model = ms[0].ID
	}
	j := &videoJob{req: req, plan: plan, VideoJob: VideoJob{
		ID: newVideoID(), Object: "video", Model: model, Status: VideoQueued,
		CreatedAt: time.Now().Unix(), Prompt: req.Prompt,
		Size:    formatSize(plan.Width, plan.Height),
		Seconds: strconv.FormatFloat(plan.Seconds, 'f', 2, 64), Quality: "standard",
		Seed: plan.Seed, Steps: plan.Steps, Frames: plan.Frames,
		Estimated: plan.Estimate.Round(time.Second).Seconds(),
	}}
	j.path = filepath.Join(q.dir, j.ID+".mp4")
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.ctx.Err() != nil {
		return VideoJob{}, fmt.Errorf("the server is shutting down")
	}
	select {
	case q.queue <- j:
	default:
		return VideoJob{}, ErrQueueFull
	}
	q.jobs[j.ID] = j
	return j.VideoJob, nil
}

// Get is one job's current state.
func (q *VideoJobs) Get(id string) (VideoJob, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	j, ok := q.jobs[id]
	if !ok {
		return VideoJob{}, false
	}
	return j.VideoJob, true
}

// List is every job, oldest first.
func (q *VideoJobs) List() []VideoJob {
	q.mu.Lock()
	out := make([]VideoJob, 0, len(q.jobs))
	for _, j := range q.jobs {
		out = append(out, j.VideoJob)
	}
	q.mu.Unlock()
	sort.Slice(out, func(a, b int) bool {
		if out[a].CreatedAt != out[b].CreatedAt {
			return out[a].CreatedAt < out[b].CreatedAt
		}
		return out[a].ID < out[b].ID
	})
	return out
}

// content is a completed job's file.
func (q *VideoJobs) content(id string) (path string, job VideoJob, ok bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	j, ok := q.jobs[id]
	if !ok {
		return "", VideoJob{}, false
	}
	return j.path, j.VideoJob, true
}

// Delete forgets a job: a queued one never runs, a running one is
// cancelled, and a finished one's file is removed.
func (q *VideoJobs) Delete(id string) bool {
	q.mu.Lock()
	defer q.mu.Unlock()
	j, ok := q.jobs[id]
	if !ok {
		return false
	}
	delete(q.jobs, id)
	j.gone = true
	if j.cancel != nil {
		j.cancel()
	}
	if j.Status == VideoCompleted || j.Status == VideoFailed {
		os.Remove(j.path)
	}
	return true
}

// work runs the queue one job at a time until Close, and expires finished
// jobs as it goes.
func (q *VideoJobs) work() {
	defer close(q.done)
	tick := time.NewTicker(time.Minute)
	defer tick.Stop()
	for {
		select {
		case <-q.ctx.Done():
			q.drain()
			return
		case <-tick.C:
			q.expire(time.Now())
		case j := <-q.queue:
			q.run(j)
		}
	}
}

// drain fails whatever is still queued at shutdown.
func (q *VideoJobs) drain() {
	for {
		select {
		case j := <-q.queue:
			q.mu.Lock()
			q.finish(j, &VideoError{Code: "server_shutdown", Message: "the server shut down before this job ran"})
			q.mu.Unlock()
		default:
			return
		}
	}
}

func (q *VideoJobs) expire(now time.Time) {
	q.mu.Lock()
	defer q.mu.Unlock()
	for id, j := range q.jobs {
		if j.ExpiresAt != nil && now.Unix() >= *j.ExpiresAt {
			delete(q.jobs, id)
			os.Remove(j.path)
		}
	}
}

// finish marks a job done, failed when e is set. q.mu is held.
func (q *VideoJobs) finish(j *videoJob, e *VideoError) {
	now := time.Now()
	done, exp := now.Unix(), now.Add(q.ttl).Unix()
	j.CompletedAt, j.ExpiresAt, j.Stage = &done, &exp, ""
	j.cancel = nil
	if e != nil {
		j.Status, j.Error = VideoFailed, e
		os.Remove(j.path)
		return
	}
	j.Status, j.Progress = VideoCompleted, 100
}

func (q *VideoJobs) run(j *videoJob) {
	ctx, cancel := context.WithCancel(q.ctx)
	defer cancel()
	q.mu.Lock()
	if j.gone {
		q.mu.Unlock()
		return
	}
	j.Status, j.cancel = VideoInProgress, cancel
	q.mu.Unlock()

	start := time.Now()
	err := q.backend.GenerateVideo(ctx, j.req, j.plan, j.path, func(p VideoProgress) {
		q.mu.Lock()
		defer q.mu.Unlock()
		j.Stage = p.Stage
		// 100 is for a job whose file is there to fetch.
		j.Progress = min(99, max(j.Progress, int(p.Fraction*100)))
	})

	q.mu.Lock()
	defer q.mu.Unlock()
	switch {
	case j.gone:
		os.Remove(j.path)
		logf(ctx, "video %s: deleted after %v", j.ID, time.Since(start).Round(time.Second))
	case err != nil && q.ctx.Err() != nil:
		q.finish(j, &VideoError{Code: "server_shutdown", Message: "the server shut down while this job ran"})
	case err != nil:
		code := "generation_failed"
		if errors.Is(err, ErrUnsupported) {
			code = "invalid_request"
		}
		logf(ctx, "video %s: failed after %v: %v", j.ID, time.Since(start).Round(time.Second), err)
		q.finish(j, &VideoError{Code: code, Message: err.Error()})
	default:
		logf(ctx, "video %s: %s, %s s, %d steps in %v", j.ID, j.Size, j.Seconds, j.Steps, time.Since(start).Round(time.Second))
		q.finish(j, nil)
	}
}

// VideoCreateRequest is POST /v1/videos's body: OpenAI's fields, SGLang's H3
// fields, and this server's extensions (steps, seed).
type VideoCreateRequest struct {
	Model  string `json:"model,omitempty"`
	Prompt string `json:"prompt"`
	// Size is OpenAI's "WIDTHxHEIGHT". It is read as an aspect ratio and a
	// short edge, and the canvas is the model's for that pair, snapped to
	// its 32-pixel grid: 1280x720 runs as 1280x704, and the job says so.
	Size string `json:"size,omitempty"`
	// Seconds is OpenAI's duration, which it sends as a string ("8").
	Seconds flexFloat `json:"seconds,omitempty"`
	// InputReference is OpenAI's keyframe, the video's first frame: a
	// multipart file, or in JSON OpenAI's {"image_url": …} (fetched if it is
	// http(s), as OpenAI fetches it) or {"file_id": …} (refused: there are no
	// files here). A bare string — a URL, a data: URL or base64 — is read too.
	InputReference json.RawMessage `json:"input_reference,omitempty"`
	inputReference []byte
	// Task and Conditions are SGLang's: "t2va", or "fl2va" with up to two
	// keyframe conditions (VIDEO.md M10).
	Task       string           `json:"task,omitempty"`
	Conditions []videoCondition `json:"conditions,omitempty"`
	Target     *struct {
		ShortEdge   int       `json:"short_edge,omitempty"`
		AspectRatio string    `json:"aspect_ratio,omitempty"`
		Duration    flexFloat `json:"duration_seconds,omitempty"`
	} `json:"target,omitempty"`
	// AspectRatio and ShortEdge are the same as Target's, at the top level.
	AspectRatio string `json:"aspect_ratio,omitempty"`
	ShortEdge   int    `json:"short_edge,omitempty"`
	Steps       int    `json:"steps,omitempty"`
	NumSteps    int    `json:"num_inference_steps,omitempty"`
	Seed        *int64 `json:"seed,omitempty"`
}

// videoCondition is one of SGLang's fl2va conditions:
// {"type": "image", "uri": ..., "role": "keyframe", "frame_index": 0}.
// The uri is fetched if it is http(s), as SGLang fetches it (the README's
// requests name CDN links), or read if it is a data: URL.
type videoCondition struct {
	Type       string `json:"type"`
	URI        string `json:"uri"`
	Role       string `json:"role,omitempty"`
	FrameIndex *int   `json:"frame_index,omitempty"`
}

// maxKeyframePixels bounds a keyframe before it is decoded: it is resized
// to the canvas anyway, and a picture past this is a mistake or a bomb.
const maxKeyframePixels = 64 << 20

// decodeKeyframe reads a keyframe's bytes as png or jpeg.
func decodeKeyframe(raw []byte) (image.Image, error) {
	cfg, _, err := image.DecodeConfig(bytes.NewReader(raw))
	if err != nil {
		return nil, fmt.Errorf("this server decodes png and jpeg: %v", err)
	}
	if cfg.Width <= 0 || cfg.Height <= 0 || cfg.Width*cfg.Height > maxKeyframePixels {
		return nil, fmt.Errorf("a %dx%d picture; keyframes are at most %d megapixels", cfg.Width, cfg.Height, maxKeyframePixels>>20)
	}
	img, _, err := image.Decode(bytes.NewReader(raw))
	if err != nil {
		return nil, fmt.Errorf("this server decodes png and jpeg: %v", err)
	}
	return img, nil
}

// imageRef is where a JSON image reference points: OpenAI's
// {"image_url": …} / {"file_id": …}, or a bare string.
func imageRef(raw json.RawMessage) (string, error) {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return s, nil
	}
	var ref struct {
		ImageURL string `json:"image_url"`
		FileID   string `json:"file_id"`
	}
	if err := json.Unmarshal(raw, &ref); err != nil {
		return "", errors.New(`an image reference is {"image_url": …}, {"file_id": …} or a string`)
	}
	switch {
	case ref.FileID != "" && ref.ImageURL != "":
		return "", errors.New("give one of image_url and file_id, not both")
	case ref.FileID != "":
		return "", fmt.Errorf("file_id %q: this server has no Files API, so send the picture as image_url", ref.FileID)
	case ref.ImageURL == "":
		return "", errors.New("an image reference with neither image_url nor file_id")
	}
	return ref.ImageURL, nil
}

// readImageRef returns the bytes of an image named by a URL (fetched, as
// OpenAI's API fetches one), a data: URL, or bare base64.
func readImageRef(ctx context.Context, ref string) ([]byte, error) {
	ref = strings.TrimSpace(ref)
	if strings.HasPrefix(ref, "http://") || strings.HasPrefix(ref, "https://") || strings.HasPrefix(ref, "data:") {
		return util.FetchImage(ctx, ref)
	}
	return decodeImageField(ref)
}

// keyframes decodes the request's keyframes: an OpenAI input_reference
// (the first frame), or SGLang's conditions. URLs are fetched here, at
// submit, so a picture that cannot be read is a 400 and not a failed job.
func (c *VideoCreateRequest) keyframes(ctx context.Context) ([]VideoKeyframe, error) {
	var out []VideoKeyframe
	if len(c.inputReference) > 0 || len(c.InputReference) > 0 {
		raw := c.inputReference
		if raw == nil {
			ref, err := imageRef(c.InputReference)
			if err != nil {
				return nil, fmt.Errorf("input_reference: %v", err)
			}
			if raw, err = readImageRef(ctx, ref); err != nil {
				return nil, fmt.Errorf("input_reference: %v", err)
			}
		}
		img, err := decodeKeyframe(raw)
		if err != nil {
			return nil, fmt.Errorf("input_reference: %v", err)
		}
		out = append(out, VideoKeyframe{Image: img})
	}
	if len(c.Conditions) > 2 || (len(out) > 0 && len(c.Conditions) > 0) {
		return nil, errors.New("fl2va takes at most two keyframes, a first and a last, from one of input_reference or conditions")
	}
	for i, cond := range c.Conditions {
		if cond.Type != "image" {
			return nil, fmt.Errorf("conditions[%d]: type %q; fl2va's conditions are images", i, cond.Type)
		}
		if cond.Role != "" && cond.Role != "keyframe" {
			return nil, fmt.Errorf("conditions[%d]: role %q; fl2va's conditions are keyframes", i, cond.Role)
		}
		raw, err := readImageRef(ctx, cond.URI)
		if err != nil {
			return nil, fmt.Errorf("conditions[%d]: %v", i, err)
		}
		img, err := decodeKeyframe(raw)
		if err != nil {
			return nil, fmt.Errorf("conditions[%d]: %v", i, err)
		}
		// Without an index, the first condition is the first frame and a
		// second one the last.
		idx := -i
		if cond.FrameIndex != nil {
			idx = *cond.FrameIndex
		}
		if idx < -1 {
			return nil, fmt.Errorf("conditions[%d]: frame_index %d", i, idx)
		}
		out = append(out, VideoKeyframe{Image: img, FrameIndex: idx})
	}
	return out, nil
}

// flexFloat is a number sent as a number or as a string.
type flexFloat float64

func (f *flexFloat) UnmarshalJSON(b []byte) error {
	s := strings.Trim(string(b), `"`)
	if s == "" || s == "null" {
		*f = 0
		return nil
	}
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return fmt.Errorf("%q is not a number", s)
	}
	*f = flexFloat(v)
	return nil
}

// parseAspect reads "16:9"; "" and "auto" are zero (the default).
func parseAspect(s string) (w, h float64, err error) {
	if s == "" || s == "auto" {
		return 0, 0, nil
	}
	a, b, ok := strings.Cut(s, ":")
	if ok {
		w, err = strconv.ParseFloat(a, 64)
		if err == nil {
			h, err = strconv.ParseFloat(b, 64)
		}
	}
	if !ok || err != nil || w <= 0 || h <= 0 {
		return 0, 0, fmt.Errorf("aspect_ratio %q is not W:H", s)
	}
	return w, h, nil
}

// toRequest turns the envelope into a VideoRequest.
func (c *VideoCreateRequest) toRequest(ctx context.Context) (*VideoRequest, error) {
	if strings.TrimSpace(c.Prompt) == "" {
		return nil, errors.New("prompt is required")
	}
	keys, err := c.keyframes(ctx)
	if err != nil {
		return nil, err
	}
	switch c.Task {
	case "", "fl2va", "i2va":
		// fl2va with no keyframe is t2va, as the model card has it.
	case "t2va":
		if len(keys) > 0 {
			return nil, errors.New("task t2va takes no keyframes; send task fl2va")
		}
	case "ref2va":
		return nil, errors.New("task ref2va (references) is not served; t2va and fl2va are")
	default:
		return nil, fmt.Errorf("unknown task %q", c.Task)
	}
	r := &VideoRequest{Model: c.Model, Prompt: c.Prompt, Seconds: float64(c.Seconds), Seed: c.Seed,
		ShortEdge: c.ShortEdge, Steps: c.Steps, Keyframes: keys}
	if r.Steps == 0 {
		r.Steps = c.NumSteps
	}
	aspect := c.AspectRatio
	if c.Target != nil {
		if c.Target.ShortEdge != 0 {
			r.ShortEdge = c.Target.ShortEdge
		}
		if c.Target.AspectRatio != "" {
			aspect = c.Target.AspectRatio
		}
		if c.Target.Duration != 0 {
			r.Seconds = float64(c.Target.Duration)
		}
	}
	if r.AspectW, r.AspectH, err = parseAspect(aspect); err != nil {
		return nil, err
	}
	if c.Size != "" && c.Size != "auto" {
		w, h, err := parseSize(c.Size)
		if err != nil {
			return nil, err
		}
		r.AspectW, r.AspectH, r.ShortEdge = float64(w), float64(h), min(w, h)
	}
	if r.Seconds < 0 || r.Steps < 0 || r.ShortEdge < 0 {
		return nil, errors.New("seconds, steps and short_edge must not be negative")
	}
	return r, nil
}

// readVideoCreate reads the body as JSON or, as OpenAI's SDK sends it, as a
// multipart form.
func readVideoCreate(ctx context.Context, w http.ResponseWriter, r *http.Request) (*VideoCreateRequest, bool) {
	var c VideoCreateRequest
	mt, _, _ := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if mt != "multipart/form-data" && mt != "application/x-www-form-urlencoded" {
		return &c, decodeJSON(ctx, w, r, &c)
	}
	if err := r.ParseMultipartForm(32 << 20); err != nil && !errors.Is(err, http.ErrNotMultipart) {
		if tooLarge(ctx, w, err) {
			return nil, false
		}
		badRequest(ctx, w, "malformed form: "+err.Error())
		return nil, false
	}
	if r.MultipartForm != nil && len(r.MultipartForm.File["input_reference"]) > 0 {
		fh := r.MultipartForm.File["input_reference"][0]
		f, err := fh.Open()
		if err == nil {
			c.inputReference, err = io.ReadAll(f)
			f.Close()
		}
		if err != nil {
			badRequest(ctx, w, "input_reference: "+err.Error())
			return nil, false
		}
	} else if v := r.FormValue("input_reference"); v != "" {
		// A form field rather than a file: a URL, a data: URL, base64, or
		// OpenAI's JSON object.
		ref := json.RawMessage(v)
		if !json.Valid(ref) || v[0] != '{' {
			ref, _ = json.Marshal(v)
		}
		c.InputReference = ref
	}
	c.Model, c.Prompt, c.Size = r.FormValue("model"), r.FormValue("prompt"), r.FormValue("size")
	c.Task, c.AspectRatio = r.FormValue("task"), r.FormValue("aspect_ratio")
	for _, f := range []struct {
		name string
		dst  any
	}{{"seconds", &c.Seconds}, {"short_edge", &c.ShortEdge}, {"steps", &c.Steps},
		{"num_inference_steps", &c.NumSteps}, {"seed", &c.Seed}} {
		v := r.FormValue(f.name)
		if v == "" {
			continue
		}
		if err := json.Unmarshal([]byte(v), f.dst); err != nil {
			badRequest(ctx, w, fmt.Sprintf("%s: %v", f.name, err))
			return nil, false
		}
	}
	return &c, true
}

func (s *Server) handleVideoCreate(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if s.Videos == nil {
		notLoaded(ctx, w, "the video model", "-video")
		return
	}
	c, ok := readVideoCreate(ctx, w, r)
	if !ok {
		return
	}
	req, err := c.toRequest(ctx)
	if err != nil {
		badRequest(ctx, w, err.Error())
		return
	}
	job, err := s.Videos.Submit(req)
	switch {
	case errors.Is(err, ErrQueueFull):
		logf(ctx, "429: %v", err)
		writeError(w, http.StatusTooManyRequests, "rate_limit_error", err.Error())
	case err != nil:
		backendError(ctx, w, "video", err)
	default:
		logf(ctx, "video %s queued: %s, %s s, %d steps, seed %d, ~%v", job.ID, job.Size, job.Seconds,
			job.Steps, job.Seed, time.Duration(job.Estimated)*time.Second)
		writeJSON(w, http.StatusOK, job)
	}
}

func (s *Server) videoJob(w http.ResponseWriter, r *http.Request) (VideoJob, bool) {
	ctx := r.Context()
	if s.Videos == nil {
		notLoaded(ctx, w, "the video model", "-video")
		return VideoJob{}, false
	}
	job, ok := s.Videos.Get(r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "invalid_request_error", "no video "+r.PathValue("id"))
	}
	return job, ok
}

func (s *Server) handleVideoGet(w http.ResponseWriter, r *http.Request) {
	if job, ok := s.videoJob(w, r); ok {
		writeJSON(w, http.StatusOK, job)
	}
}

// VideoList is GET /v1/videos's page.
type VideoList struct {
	Object  string     `json:"object"` // "list"
	Data    []VideoJob `json:"data"`
	FirstID *string    `json:"first_id"`
	LastID  *string    `json:"last_id"`
	HasMore bool       `json:"has_more"`
}

func (s *Server) handleVideoList(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if s.Videos == nil {
		notLoaded(ctx, w, "the video model", "-video")
		return
	}
	qv := r.URL.Query()
	limit := 20
	if v := qv.Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > 100 {
			badRequest(ctx, w, "limit must be 1-100")
			return
		}
		limit = n
	}
	jobs := s.Videos.List()
	switch qv.Get("order") {
	case "", "desc":
		for i, j := 0, len(jobs)-1; i < j; i, j = i+1, j-1 {
			jobs[i], jobs[j] = jobs[j], jobs[i]
		}
	case "asc":
	default:
		badRequest(ctx, w, "order must be asc or desc")
		return
	}
	if after := qv.Get("after"); after != "" {
		for i := range jobs {
			if jobs[i].ID == after {
				jobs = jobs[i+1:]
				break
			}
		}
	}
	out := VideoList{Object: "list", Data: jobs}
	if len(jobs) > limit {
		out.Data, out.HasMore = jobs[:limit], true
	}
	if n := len(out.Data); n > 0 {
		out.FirstID, out.LastID = &out.Data[0].ID, &out.Data[n-1].ID
	}
	writeJSON(w, http.StatusOK, out)
}

func (s *Server) handleVideoContent(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if s.Videos == nil {
		notLoaded(ctx, w, "the video model", "-video")
		return
	}
	if v := r.URL.Query().Get("variant"); v != "" && v != "video" {
		badRequest(ctx, w, fmt.Sprintf("variant %q is not served; only video", v))
		return
	}
	path, job, ok := s.Videos.content(r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "invalid_request_error", "no video "+r.PathValue("id"))
		return
	}
	if job.Status != VideoCompleted {
		writeError(w, http.StatusConflict, "invalid_request_error",
			fmt.Sprintf("video %s is %s, not completed", job.ID, job.Status))
		return
	}
	f, err := os.Open(path)
	if err != nil {
		// Deleted or expired between the lookup and the open.
		writeError(w, http.StatusNotFound, "invalid_request_error", "no video "+job.ID)
		return
	}
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		serverError(ctx, w, "video content", err)
		return
	}
	w.Header().Set("Content-Type", "video/mp4")
	w.Header().Set("Content-Disposition", `inline; filename="`+job.ID+`.mp4"`)
	http.ServeContent(w, r, "", st.ModTime(), f)
}

func (s *Server) handleVideoDelete(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if s.Videos == nil {
		notLoaded(ctx, w, "the video model", "-video")
		return
	}
	id := r.PathValue("id")
	if !s.Videos.Delete(id) {
		writeError(w, http.StatusNotFound, "invalid_request_error", "no video "+id)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"id": id, "object": "video.deleted", "deleted": true})
}

content.content:
- The questions are **isolated**. Rewriting or removing one leaves every
  other answer bit-identical (`TestGPUQuestionsAreIsolated`). Options inside
  one question are *not* independent, and reordering them can move the
  answer. That is Kev's and Jev's behaviour, not a defect of this server.

## Videos are jobs

A video is minutes at the served 480p and hours at the trained 768p
(VIDEO.md), so `/v1/videos` is OpenAI's asynchronous shape and not a request
that waits: `POST` answers at once with a job, the client polls `GET
/v1/videos/{id}` until `status` is `completed` (or `failed`, with an `error`),
and fetches `GET /v1/videos/{id}/content`, an H.264/AAC mp4. `DELETE` cancels
a queued or running job — within one ≤ 800 ms submission — and forgets it. A
finished job and its file are kept for `-video-ttl` and then 404, as does
everything after a restart: jobs live in memory.

```sh
curl -s localhost:8080/v1/videos -H 'Content-Type: application/json' \
  -d '{"prompt": "…", "size": "864x480", "seconds": "5"}'          # OpenAI's shape
curl -s localhost:8080/v1/videos -H 'Content-Type: application/json' \
  -d '{"task": "t2va", "prompt": "…", "seed": 0,
       "target": {"short_edge": 768, "aspect_ratio": "16:9", "duration_seconds": 10}}'  # SGLang's
curl -s localhost:8080/v1/videos -F prompt="…" -F input_reference=@start.png          # OpenAI's, from a first frame
curl -s localhost:8080/v1/videos -H 'Content-Type: application/json' \
  -d '{"task": "fl2va", "prompt": "…", "target": {"short_edge": 480, "aspect_ratio": "auto"},
       "conditions": [{"type": "image", "uri": "data:image/png;base64,…", "role": "keyframe", "frame_index": 0},
                      {"type": "image", "uri": "data:image/jpeg;base64,…", "role": "keyframe", "frame_index": -1}]}'
```

Both envelopes are read, and a multipart form as OpenAI's SDK sends one.
**`size` is read as an aspect ratio and a short edge**, not a canvas: the
model's canvases are on a 32-pixel grid, so `1280x720` runs as 1280x704 and
the job's `size` says so. `seconds` below the model's 5 s floor is raised
to it (OpenAI's clients default to "4"); past 15 s is a 400. So is a request
the transformer's arenas cannot span — 87,296 rows, which is the trained
768p canvas to ~11.8 s — and that is found at submit time, before 50 GB of
text encoder is staged for it. Extensions: `steps` (or
`num_inference_steps`; default 20, the release's 50), `seed` (reported
either way), and on the job `seed`, `steps`, `frames`, `stage` and
`estimated_seconds`, the backend's estimate of the run from measured rates.
`variant` other than `video` is a 400.

**Keyframes (`fl2va`, VIDEO.md M10)** pin the video's first frame, its last,
or both. OpenAI's `input_reference` is the first frame: a multipart file, or in JSON
OpenAI's `{"image_url": …}` (an http(s) URL is fetched, as OpenAI fetches it;
a data: URL is read) — `{"file_id": …}` is a 400, there being no Files API —
or, leniently, a bare URL or base64 string. SGLang's `conditions` are up to
two images with a `frame_index`: 0 is the first frame, and -1 — or any index
at or past the last requested frame — is the last; without one, the first
condition is the first frame and a second the last. A condition's `uri` is
fetched the same way (SGLang fetches it too), so the README's requests run
unchanged. URLs are fetched at submit, so an unreadable picture is a 400 and
not a failed job; the fetch is the chat images' (50 MB, 60 s). png and jpeg
are read, up to 64 megapixels. With no `size` and `aspect_ratio`
`auto` (or none), the canvas takes the first keyframe's aspect ratio; the
first keyframe is stretched onto the canvas and a second one cover-cropped,
as the reference pipeline does. `task: t2va` with a keyframe, or `ref2va`
(references, VIDEO.md M13), is a 400.

**The queue is in `api`, and one job runs at a time.** The backend is
synchronous — one mp4 to a path — and a request's stagings peak at ~50 GB,
so two at once would not fit. **The device is not held for the job.** The
stagings (~2 of a request's minutes, reading bf16 from disk) allocate and
write mapped memory and never touch the queue, so they take no lock; what
does — the encoder's forward, each transformer forward, the VAE decode —
yields the device between submissions, so a speech request behind a 35 s
forward waits for one submission, not the forward.

## What is left

- **Constrained decoding**, which is the one refusal above that is a missing
  capability rather than a missing shape. It would close `response_format`,
  `text.format` and a `tool_choice` that names a function in one go.
- **More than one conversation at a time is interleaved, not batched.**
  `-llm-slots` holds several and a scheduler shares the device between them
  (above), but each pass is still one sequence's single row, so N streams
  split one stream's rate. Batched decode — the decoding slots' tokens as rows
  of one pass — is CONCURRENCY.md's C5.
- **MTP speculative decoding is built, lossless, and parked at 0.95x**
  (research/p5c-speculative-loop.md) — it costs nothing while off. What
  would make it pay is the draft head's acceptance on a real workload,
  which is a measurement (`cmd/llm -mtp`), not engineering; see `TODO.md`.
- **Image editing costs more than it did**, and that is the model rather
  than the port: an edit in 2.1 is a conditional generation over a 27-layer
  vision tower (research/qimage-vertical.md Q8), not an SDEdit, so there is no truncated
  schedule to make it cheap. 1m54s at 1024² against a generation's 1m28.8s, and
  no `strength` to trade quality for time with. The endpoint's shape is
  unchanged underneath; what changed is that `image[]` is a real list.
- **The image adapter holds the device lock for the whole run**, where the
  language model's takes it per forward pass. The same fix applies — between
  two denoising steps there is no work in flight — but it would mean the
  pipeline calling back out around every submit, and a step at 1024x1024 is
  1.7 s, so what a speech request waiting behind it would actually gain is a
  measurement rather than an argument.
- **`n > 1` images are serial**, and capped at four, because the device lock
  is. Four 1024x1024 images is a minute in one request.
- **A forced alignment** for the transcript timings, if the 80 ms grid and the
  duration head's approximation ever turn out not to be enough.
package backend

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"math/rand"
	"sync"
	"time"

	"strix-halo-vulkan/api"
	"strix-halo-vulkan/h3/pipeline"
	"strix-halo-vulkan/h3/plan"
	"strix-halo-vulkan/vk"
	"strix-halo-vulkan/zimage/qwen"
)

// VideoOptions is what cmd/serve's flags come to.
type VideoOptions struct {
	// Model is the MiniMax-H3 checkpoint root (transformer/, text_encoder/,
	// vae/, audio_vae/, tokenizer/).
	Model string
	// Device is required: a forward is 35 s on the device at 480p.
	Device *Device
	// MaxPrompt caps a prompt's tokens (0: pipeline.DefaultMaxPrompt).
	MaxPrompt int
	// FP16 stages the text encoder and the transformer in fp16, the
	// control; the default is their int8 banks (VIDEO.md M11a).
	FP16 bool
	// ID is the model id this backend answers to.
	ID string
}

const defaultVideoModelID = "minimax-h3"

// Video is the MiniMax-H3 adapter: an api.VideoBackend over h3/pipeline.
//
// **Nothing is resident between requests.** A request stages the text
// encoder (50 GB), frees it, stages the transformer (44 GB), frees it, and
// stages the video VAE (7 GB), so the process holds the host-side pieces
// (tokenizer, audio decoder: 0.3 GB) at rest and ~50 GB at a request's peak
// (VIDEO.md decision 2, M-o5).
//
// **The device is shared, in two ways** (VIDEO.md M9). The stagings do not
// take it at all: they allocate, build pipelines and write mapped memory,
// and none of that touches the queue, so ~2 minutes of a request's disk
// reads run while speech and images have the device. What does take it --
// the encoder's forward, each transformer forward, the VAE decode -- yields
// it between submissions (each ≤ 800 ms by construction) to whoever is
// waiting, so a speech request queued behind a 35 s forward waits for one
// submission rather than the forward.
type Video struct {
	opt  VideoOptions
	id   string
	pipe *pipeline.Pipeline

	mu  sync.Mutex // rng
	rng *rand.Rand
}

// NewVideo loads the host-side pieces. Nothing is staged on the device.
func NewVideo(opt VideoOptions) (*Video, error) {
	if opt.ID == "" {
		opt.ID = defaultVideoModelID
	}
	if opt.Device == nil {
		return nil, fmt.Errorf("backend: the video pipeline needs a device; there is no host path for it")
	}
	d := opt.Device
	bank := qwen.BankQ8
	if opt.FP16 {
		bank = qwen.BankFP16
	}
	p, err := pipeline.New(d.dev, opt.Model, pipeline.Options{
		MaxPrompt: opt.MaxPrompt,
		Bank:      bank,
		Hold: func(fn func() error) error {
			return d.Do(func(*vk.Device) error { return fn() })
		},
		Between: func() { d.yield() },
	})
	if err != nil {
		return nil, fmt.Errorf("backend: loading %s: %w", opt.Model, err)
	}
	return &Video{opt: opt, id: opt.ID, pipe: p, rng: rand.New(rand.NewSource(rand.Int63()))}, nil
}

// Models reports the one model this backend serves.
func (b *Video) Models() []api.Model {
	return []api.Model{{ID: b.id, Object: "model", OwnedBy: "local"}}
}

// VideoGeometry is what a request may ask for.
func (b *Video) VideoGeometry() api.VideoGeometry {
	h, w, _ := plan.Canvas(16, 9, pipeline.DefaultShortEdge, plan.MaxPixels)
	return api.VideoGeometry{
		DefaultSize:    fmt.Sprintf("%dx%d", w, h),
		DefaultSeconds: pipeline.DefaultSeconds,
		MinSeconds:     plan.MinDuration, MaxSeconds: plan.MaxDuration,
		MaxShortEdge: plan.ShortEdge,
		DefaultSteps: pipeline.DefaultSteps,
		FPS:          plan.FPS,
		SampleRate:   b.pipe.SampleRate(),
	}
}

// Close frees whatever is staged. The job queue must be closed first.
func (b *Video) Close() {
	b.pipe.Close()
}

// request is the pipeline's request for an API one; seed is the resolved
// seed.
//
// **A duration under the model's 5 s floor is raised to it** rather than
// refused. OpenAI's default is 4 s and its clients send "4"; what they get
// is 5.17 s, and the job's `seconds` says so. Past 15 s is refused: that is
// a clip of a different length, not a rounding.
//
// A keyframe's frame_index is read against the requested length: 0 is the
// first frame, and -1 or any index at or past the last requested frame is
// the last (a client counting in the aligned 17n + 5 frames lands past it,
// which is the same frame). fl2va pins nothing in between.
func request(req *api.VideoRequest, seed int64) (*pipeline.Request, error) {
	secs := req.Seconds
	if secs != 0 && secs < plan.MinDuration {
		secs = plan.MinDuration
	}
	p := &pipeline.Request{
		Prompt: req.Prompt, AspectW: req.AspectW, AspectH: req.AspectH, ShortEdge: req.ShortEdge,
		Seconds: secs, Steps: req.Steps, Seed: uint64(seed),
	}
	last := int((cmp.Or(secs, pipeline.DefaultSeconds))*plan.FPS) - 1
	for i, k := range req.Keyframes {
		switch {
		case k.FrameIndex == 0 && p.First == nil:
			p.First = k.Image
		case (k.FrameIndex == -1 || k.FrameIndex >= last) && p.Last == nil:
			p.Last = k.Image
		case k.FrameIndex == 0 || k.FrameIndex == -1 || k.FrameIndex >= last:
			return nil, fmt.Errorf("two keyframes for the same end of the video: %w", api.ErrUnsupported)
		default:
			return nil, fmt.Errorf("keyframe %d pins frame %d; fl2va pins the first (0) and the last (-1, or %d here): %w",
				i, k.FrameIndex, last, api.ErrUnsupported)
		}
	}
	return p, nil
}

// PlanVideo resolves a request on the host: tokenises the prompt, fixes the
// canvas and frame count, and checks the transformer's arenas can span it.
func (b *Video) PlanVideo(req *api.VideoRequest) (*api.VideoPlan, error) {
	seed := int64(0)
	if req.Seed != nil {
		seed = *req.Seed
	} else {
		b.mu.Lock()
		seed = b.rng.Int63()
		b.mu.Unlock()
	}
	if seed < 0 {
		return nil, fmt.Errorf("seed %d is negative: %w", seed, api.ErrUnsupported)
	}
	preq, err := request(req, seed)
	if err != nil {
		return nil, err
	}
	r, err := b.pipe.Resolve(preq)
	if err != nil {
		// Every Resolve failure is the request's: steps, canvas, duration,
		// a prompt past the cap, rows past the arenas.
		return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	return &api.VideoPlan{
		Width: r.Width, Height: r.Height, Frames: r.Frames,
		Seconds: float64(r.Frames) / plan.FPS,
		Steps:   r.Steps, Seed: seed, PromptTokens: len(r.Tokens),
		Estimate: estimate(r).total(),
	}, nil
}

// cost is a request's expected wall time by stage.
type cost struct {
	encode, stage, forward time.Duration // forward is one of Steps − 1
	forwards               int
	decode                 time.Duration
}

func (c cost) total() time.Duration {
	return c.encode + c.stage + time.Duration(c.forwards)*c.forward + c.decode
}

// estimate prices a request from M7/M8's measurements. A forward is
// a·L + b·L² in its L rows, fitted through 35.6 s at 15,936 rows and 143 s at
// 38,247 (7.7 s predicted at 5,095, where 7.4 was measured). The fixed costs
// are M8's: the encoder staged and run beside the tables (82 s), the
// transformer's staging (53 s), and the VAE's (7 s) plus 2.5 ms a video row
// of decode (38 s at 480p). fl2va's keyframes add the VAE encoder and the
// vision tower to the encode (M10: 88 s against 82 with one keyframe); their
// rows are already in L.
func estimate(r *pipeline.Resolved) cost {
	L := float64(len(r.Layout.Pos))
	fwd := 1.159e-3*L + 6.745e-8*L*L
	encode := 82 * time.Second
	if len(r.Keyframes) > 0 {
		encode += 6 * time.Second
	}
	return cost{
		encode:   encode,
		stage:    53 * time.Second,
		forward:  time.Duration(fwd * float64(time.Second)),
		forwards: r.Steps - 1,
		decode:   7*time.Second + time.Duration(2.5e-3*float64(len(r.Layout.Video))*float64(time.Second)),
	}
}

// GenerateVideo runs a planned request and muxes it to dst.
func (b *Video) GenerateVideo(ctx context.Context, req *api.VideoRequest, vp *api.VideoPlan, dst string, progress func(api.VideoProgress)) error {
	preq, err := request(req, vp.Seed)
	if err != nil {
		return err
	}
	r, err := b.pipe.Resolve(preq)
	if err != nil {
		return fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	c := estimate(r)
	total := c.total().Seconds()
	at := func(d time.Duration) float64 { return d.Seconds() / total }
	res, err := b.pipe.Generate(ctx, preq, func(s pipeline.Stage, done, n int) {
		var f float64
		switch s {
		case pipeline.StageEncode:
			f = 0
		case pipeline.StageTransform:
			f = at(c.encode)
		case pipeline.StageStep:
			f = at(c.encode+c.stage) + at(time.Duration(done)*c.forward)
		case pipeline.StageDecode:
			f = at(c.total() - c.decode)
		}
		progress(api.VideoProgress{Stage: string(s), Fraction: f})
	})
	if err != nil {
		if errors.Is(err, context.Canceled) {
			return err
		}
		return fmt.Errorf("h3: %w", err)
	}
	progress(api.VideoProgress{Stage: "mux", Fraction: 0.99})
	return pipeline.WriteMP4(dst, res)
}

