	if req.Seed != nil {
		p.Seed = *req.Seed
	}
	if req.LMSeed != nil {
		p.LMSeed = *req.LMSeed
	}
	r := musicRequest(req)
	switch {
	case req.Duration > 0:
		p.Seconds = float64(musicLatents(r, req.Thinking)*plan.Hop) / plan.SampleRate
	case !req.Thinking:
		p.Seconds = plan.FallbackSeconds
	}
